  const chapterNames = ['先缩小问题', '自己查', '再追问', '变成行动'];
  const chapterIcons = ['search', 'book', 'question', 'check'];
  const rails = [
    { x: 272, y: 476, w: 733, h: 103 }, { x: 272, y: 507, w: 733, h: 88 },
    { x: 460, y: 447, w: 737, h: 99 }, { x: 478, y: 518, w: 731, h: 91 },
  ];
  const corner = { x: 984, y: 26, w: 235, h: 54 };

  function badge(bounds, index, active) {
    const { x, y, w, h } = bounds;
    const stacked = ease(58,87,h);
    box(g, x + 2, y + 4, w, h, 10, '#26322f84');
    box(g, x, y, w, h, 10, active ? '#e5bd83' : '#cdd7b8', active ? '#a37b48' : '#879889', 3);
    rect(g, x + 7, y + 6, w - 14, 2, active ? '#ffe5aa' : '#e5e7c5');
    fillText(g, String(index + 1), x + lerp(18,21,stacked), y + lerp(h*.5,21,stacked), lerp(18,21,stacked),
      { align: 'center', color: active ? '#785238' : '#65816e', weight: 850 });
    const iconSize = lerp(20,36,stacked);
    alpha(stacked, () => icon(chapterIcons[index], x + (w-iconSize)/2, y+14, iconSize,iconSize,1,c.ink,2.6));
    fillText(g, chapterNames[index], x + w / 2 + 9 * (1-stacked), y + lerp(h*.51,h-25,stacked),
      lerp(26,28,stacked), { align: 'center', color: c.ink, maxWidth: w - lerp(36,15,stacked), weight: 850 });
    if (active) line(g, x + 8, y + h - 5, x + w - 8, y + h - 5, '#f4da9c', 3);
  }

  const railBounds = (rect, index) => {
    const w = (rect.w - 36) / 4;
    return { x: rect.x + index * (w + 12), y: rect.y, h: rect.h, w };
  };

  function chapterRail(active, f, { omit = -1 } = {}) {
    const bounds = rails[active];
    const hits = M.rails[active];
    const items = chapterNames.map((_, index) => railBounds(bounds, index));
    alpha(out(hits[0] - 8, hits[0] + 12, f), () => line(g, bounds.x, bounds.y + bounds.h / 2,
      bounds.x + bounds.w, bounds.y + bounds.h / 2, '#8c9a78', 3));
    for (const [index, home] of items.entries()) {
      if (index === omit) continue;
      const p = out(hits[index] - 13, hits[index], f);
      alpha(p, () => badge(moveBox(home, (index - 1.5) * 24 * (1 - p), 19 * (1 - p)), index, active === index));
    }
  }

  function chapterOne(f, { entry = 1, omit = -1, contained = false } = {}) {
    if (!contained) flatDesk();
    alpha(entry, () => {
      g.translate(0, 163 * (1 - entry));
      chapterOneSheet(f, omit);
    });
    if (!contained) titlePlaque(90, 1);
  }

  function chapterOneSheet(f, omit) {
    notebook({ x: 217, y: 133, w: 846, h: 478 });
    const [num, title] = C['chapter-directions'].split('　');
    tag(num, { x: 328, y: 246, w: 125, h: 40 }, 'dusk');
    const letters = M.chapterOneLetters;
    const writing = letters.findIndex(at => at > f);
    const progress = writing < 0 ? 1 : (writing + ease(letters[writing] - 9, letters[writing], f)) / letters.length;
    const x = 640 - textWidth(title, 61, 840) / 2;
    const tip = write(title, x, 337, 61, progress, c.ink, 840);
    const rule = out(M.chapterOneLetters.at(-1), M.chapterOneLetters.at(-1) + 17, f);
    line(g, 470, 380, lerp(470, 810, rule), 380, '#b58e58', 3);
    chapterRail(0, f, { omit });
    const retract = ease(M.chapterOneLetters.at(-1), M.chapterOneLetters.at(-1) + 18, f);
    const first = M.chapterOneLetters[0];
    alpha(out(first - 14, first - 7, f) * (1 - retract), () => pencil([tip[0] + 113 * retract, tip[1] - 43 * retract], -.69, .91));
  }

  function tile(bounds, name, artName, tone = 'green', draw = 1) {
    const { x, y, w, h } = bounds;
    const fills = tone === 'gold' ? ['#e9c993','#b38854','#7b5b42'] : ['#c3d5b8','#759985','#586859'];
    box(g, x + 4, y + 7, w, h, 11, '#2536319c');
    box(g, x, y, w, h, 10, fills[0], fills[1], 3);
    const size = Math.min(h - 17, w * .29);
    icon(artName, x + 13, y + (h - size) / 2, size, size, draw, fills[2], 2.5);
    fillText(g, name, x + size + 23, y + h / 2, Math.min(26, h * .46), { color: c.ink, weight: 810, maxWidth: w - size - 25 });
  }


  function chapterTwo(f, omit = -1) {
    flatDesk();
    notebook({ ...pageHome });
    const [number, headline] = C['chapter-research'].split('　');
    const length = D.timeline.find(shot => shot.id === 'chapter-two').frames;
    const { heading, directions } = M.chapterTwo;
    const first = out(heading - 24, heading, f);
    alpha(first * (1 - ease(length - 28, length - 13, f)), () =>
      tag(number, { x: 321, y: 221, w: 130, h: 43 }, 'dusk'));
    alpha(first, () => fillText(g, headline, 645, 327 + 24 * (1-first), 54,
      { align: 'center', color: c.ink, weight: 850 }));
    const row = out(directions - 22, directions, f);
    alpha(row, () => {
      const y = 395 + 15 * (1-row);
      tile({ x: 418, y, w: 194, h: 60 }, '前端', 'project', 'green');
      tile({ x: 657, y, w: 194, h: 60 }, '后端', 'server', 'gold');
    });
    chapterRail(1, f, { omit });
  }

  function studyEntry(index, f) {
    return out(M.study.cards[index] - 24, M.study.cards[index], f);
  }

  function studyOffset(index, f) {
    const p = 1 - studyEntry(index, f);
    return [(index ? 42 : -42) * p, 12 * p];
  }

  function studyLabel(home, target, index, f) {
    const [dx, dy] = studyOffset(index, f);
    const p = ease(M.study.gather, M.study.settle, f);
    const slot = mixBox(moveBox(home, dx, dy), target, p);
    return moveBox(slot, 0, -Math.sin(Math.PI * p) * 17);
  }

  function carriedProject(f) {
    const stable = studyLabel(noteHome, projectLink, 0, f);
    const move = ease(M.study.peel, studyDuration + 20, f);
    const current = mixBox(stable, photoTag, move);
    current.y -= Math.sin(Math.PI * move) * 54;
    return current;
  }

  function research(f, showNote = true) {
    flatDesk();
    notebook({ ...pageHome });
    const tabCopy = C['research-directions'].split('　｜　');
    const dock = ease(M.study.interest + 36, M.study.cards[0] - 25, f);
    for (const [i, value] of tabCopy.entries()) {
      const shown = out(M.study.tabs[i] - 11, M.study.tabs[i], f);
      const bounds = moveBox(mixBox(browseTabs[i], deptTabs[i], dock), 0, 22 * (1 - shown));
      const art = ['project','server','book'][i];
      const choose = i === 1 ? out(M.study.interest - 2, M.study.interest + 7, f) : 0;
      alpha(shown, () => {
        tile(bounds, value, art, 'green');
        alpha(choose, () => tile(bounds, value, art, 'gold'));
      });
      FX.gleam(g, bounds, f - M.study.tabs[i], '#fff0be', 10);
      if (i === 1) {
        const age = f - M.study.interest;
        const life = out(0, 10, age) * (1 - ease(M.study.cards[0] - 20, M.study.cards[0] + 3, f));
        const pin = { x:bounds.x + bounds.w/2 - 63, y:bounds.y + bounds.h + 14 + 9*(1-life), w:126, h:34 };
        alpha(life, () => {
          const x = pin.x + pin.w/2;
          const y = pin.y;
          polygon([[x-8,y+2],[x,y-8],[x+8,y+2]], '#cfa670');
          tag('感兴趣', pin, 'gold', 23);
        });
        FX.gleam(g, bounds, age, '#fff2b9', 18);
        FX.sparks(g, bounds.x+bounds.w-10, bounds.y+14, age,
          {direction:-25,range:57,count:13,life:18,color:'#f5d49a',paper:true});
      }
    }
    const comparison = [
      { x: 282, y: 275, w: 316, h: 244, title: '岗位要的', icon: 'project', color: '#b5d1c6' },
      { x: 682, y: 275, w: 316, h: 244, title: '我做过的', icon: 'paper', color: '#d1d8ad' },
    ];
    const highlight = out(M.study.gap - 4, M.study.gap + 11, f);
    const gather = ease(M.study.gather, M.study.settle, f);
    for (const [i, card] of comparison.entries()) {
      const [dx, dy] = studyOffset(i, f);
      const x = card.x + dx, y = card.y + dy;
      alpha(studyEntry(i, f) * (1 - .28 * gather), () => {
        paper(g, x, y, card.w, card.h, { layers: 2, depth: .95, face: '#e9dbb2' });
        rect(g, x + 11, y + 11, card.w - 22, 43, card.color);
        fillText(g, card.title, x + 23, y + 32, 28, { color: c.ink, weight: 850 });
        icon(card.icon, x + 83, y + 60, 152, 96, 1, c.ink, 4);
        const start = x + 57;
        line(g, start, y + 226, x + card.w - 57, y + 226, '#a98259', i ? 2 : 3);
        alpha(highlight * (1 - gather), () => line(g, start, y + 226, lerp(start, x + card.w - 57, highlight),
          y + 226, i ? '#65917d' : '#b17c4f', 5));
      });
    }
    const hit = FX.wave(f - M.study.gap, 12);
    const size = 48 + hit * 13;
    const gapY = lerp(397, 571, gather);
    alpha(out(M.study.cards[1] + 3, M.study.cards[1] + 18, f) * (1 - gather), () => {
      line(g, 598, 397, 682, 397, '#7f9b85', 3);
    });
    alpha(gather, () => {
      box(g, 321, 539, 644, 64, 10, '#e3e6c6', '#91a68a', 3);
      const leftEnd = lerp(615, 566, gather);
      const rightEnd = lerp(718, 669, gather);
      for (const [start, end] of [[615,leftEnd],[718,rightEnd]]) {
        line(g, start, 571, end, 571, '#638372', 3);
        line(g, end, 571, end+9, 563, '#638372', 3);
        line(g, end, 571, end+9, 579, '#638372', 3);
      }
    });
    alpha(out(M.study.cards[1] + 3, M.study.cards[1] + 18, f), () => {
      const center = lerp(W / 2, 642, gather);
      tag('？', { x: center - size / 2, y: gapY - size / 2, w: size, h: size }, 'gold', 26 + hit * 4);
    });
    alpha(studyEntry(1, f), () => tag('课程作业', studyLabel(courseHome, courseLink, 1, f), 'green', 25));
    if (showNote && studyEntry(0, f) > 0) {
      const bounds = carriedProject(f);
      alpha(studyEntry(0, f), () => tag('项目经历', bounds, 'green', 25));
      alpha(ease(M.study.gap - 5, M.study.gap + 3, f), () => tag('项目经历', bounds, 'gold', 25));
      FX.gleam(g, bounds, f - M.study.gap, '#fff1b6', 17);
    }
  }

