  function reflect(f) {
    page('从做过的事里看方向');
    const cols = [
      { x: 333, title: '喜欢做？', icon: 'love', color: '#557864', tags: ['做个小功能', '把页面调顺'] },
      { x: 676, title: '还要学？', icon: 'book', color: '#90633c', tags: ['查报错', '拆成小步骤'] },
    ];
    cols.forEach((card, i) => {
      const at = M.reflectPanels[i];
      const open = out(at - 13, at, f);
      const x = card.x + (i ? 67 : -67) * (1 - open);
      alpha(open, () => {
        writingPanel(x, 259, 294, 290);
        icon(card.icon, x + 47, 278, 51, 48, 1, card.color, 3.4);
        fillText(g, card.title, x + 112, 302, 32, { color: card.color, weight: 870 });
        line(g, x + 31, 336, x + 263, 336, '#ac9a73', 2);
        card.tags.forEach((label, row) => {
          const at = M.reflection[i * 2 + row];
          const p = out(at - 13, at, f);
          alpha(p, () => tag(label, { x: x + 29 + (i ? 35 : -35) * (1 - p), y: 359 + row * 70, w: 232, h: 52 }, i ? 'gold' : 'green', 27));
        });
      });
    });
  }

